    //   추정 주소로 내보내면 «엉뚱한 곳으로 조용히» 나간다. 불릴 때 드러나게 실패시킨다.
    throw { bizMessage: "제출 주소를 찾지 못했습니다(전환 미완) — bbs.do", unresolved: "action:bbs.do" };
};


///////// 5. 일반/업무 함수 영역 /////////

/**
 * @method
 * @name scwin.changePage
 * @author Inswave
 * @date 2026. 09. 29
 * @param ver1 ver2
 * @returns
 * @hidden N
*/
scwin.changePage = async function (ver1, ver2) {
    /* sdd-asis-lifecycle:begin changePage — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    const form = (document.moveForm || { elements: [] });
    if ('1' === ver1) {
        $c.util.getComponent('dma_changePageReq').set('nowPage', ver2);
    } else {
        if ('2' === ver1) {
            $c.util.getComponent('dma_changePageReq').set('nowPage', '20');
            $c.util.getComponent("dma_scriptDts_ListReq").set("method", 'loadDetail');
        } else {
            if ('3' === ver1) {
                $c.util.getComponent('dma_changePageReq').set('nowPage', '30');
                form.action = '/lstinvstg/bbs.do';
                $c.util.getComponent("dma_scriptDts_ListReq").set("method", 'searchCommentLetterList');
            } else {
                if ('4' === ver1) {
                    $c.util.getComponent('dma_changePageReq').set('nowPage', '40');
                }
            }
        }
    }
    await scwin.tx_changePage();
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.goWriteBBS
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.goWriteBBS = async function () {
    /* sdd-asis-lifecycle:begin fn_goWriteBBS — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    const frm = (document.CommentLetterInfoForm || { elements: [] });
    frm.action = 'bbs.do';
    $c.util.getComponent("dma_scriptDts_ListReq").set("method", 'writeCommentLetter');
    { const nr = await scwin.tx_fn_goWriteBBS(); if (nr && nr.responseJSON && nr.responseJSON.success === true) { $c.win.moveUrl("/jldfil51310/jldfil51310.xml", { "method": 'writeCommentLetter' }); } };
    /* sdd-asis-lifecycle:end */
};


