    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.searchCommentLetterView
 * @author Inswave
 * @date 2026. 09. 29
 * @param contnId contnGrpId ansObjContnId listInvstgBbsTpCd contnAttachSeq
 * @returns
 * @hidden N
*/
scwin.searchCommentLetterView = async function (contnId, contnGrpId, ansObjContnId, listInvstgBbsTpCd, contnAttachSeq) {
    /* sdd-asis-lifecycle:begin fn_SearchCommentLetterView — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    const frm = (document.CommentLetterListForm || { elements: [] });
    frm.action = 'bbs.do';
    $c.util.getComponent("dma_scriptDts_ListReq").set("method", 'searchCommentLetterView');
    $c.util.getComponent('dma_changePageReq').set('contnId', contnId);
    $c.util.getComponent('dma_changePageReq').set('contnGrpId', contnGrpId);
    $c.util.getComponent('dma_changePageReq').set('ansObjContnId', ansObjContnId);
    $c.util.getComponent('dma_changePageReq').set('listInvstgBbsTpCd', listInvstgBbsTpCd);
    $c.util.getComponent('dma_changePageReq').set('contnAttachSeq', contnAttachSeq);
    { const nr = await scwin.tx_fn_SearchCommentLetterView(); if (nr && nr.responseJSON && nr.responseJSON.success === true) { $c.win.moveUrl("/jldfil51320/jldfil51320.xml", { "method": 'searchCommentLetterView', "contnId": contnId, "contnGrpId": contnGrpId, "ansObjContnId": ansObjContnId, "listInvstgBbsTpCd": listInvstgBbsTpCd, "contnAttachSeq": contnAttachSeq }); } };
    /* sdd-asis-lifecycle:end */
};



/**
 * @event
 * @name scwin.krxpage_pagenavigator_122_onclick
 * @author Inswave
 * @date 2026. 09. 29
 * @param index
 * @returns
 * @hidden N
*/
scwin.krxpage_pagenavigator_122_onclick = function (index) { const pi = (index && typeof index === 'object') ? index.newSelectedIndex : index; try { $c.util.getComponent('dma_changePageReq').set('pageIndex', pi); } catch (e) { $c.exception.handleError(e, { notify: 'none', context: 'krxpage_pagenavigator_122.page' }); } scwin.tx_changePage(); };
